public class Vector3D_crossProduct_TriageGen1Test {

    private static final double EPSILON = 1e-10;



    @Test
    public void testCrossProduct_ZeroVector() {
        Vector3D v = new Vector3D(1.0, 2.0, 3.0);
        Vector3D zero = new Vector3D(0.0, 0.0, 0.0);

        // v x 0 = 0
        assertVectorEquals(zero, Vector3D.crossProduct(v, zero));
        // 0 x v = 0
        assertVectorEquals(zero, Vector3D.crossProduct(zero, v));
    }









    private void assertVectorEquals(Vector3D expected, Vector3D actual) {
        Assert.assertEquals("X component mismatch", expected.getX(), actual.getX(), EPSILON);
        Assert.assertEquals("Y component mismatch", expected.getY(), actual.getY(), EPSILON);
        Assert.assertEquals("Z component mismatch", expected.getZ(), actual.getZ(), EPSILON);
    }
}

